onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl27_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("58-1")		    if dialog.show("Level27-1", faceShengqi) ==1 then break end			if dialog.show("Level27-2", faceShijin) ==1 then break end			if dialog.show("Level27-3", faceRenzhen) ==1 then break end			sound.play("61-2")			if dialog.show("Level27-4", faceWunai) ==1 then break end		    if dialog.show("Level27-5", faceBujie) ==1 then break end			if dialog.show("Level27-6", faceWeixiao) ==1 then break end		    if dialog.show("Level27-7", faceZhoumei) ==1 then break end			if dialog.show("Level27-8", faceWeixiao) ==1 then break end			global.setBool("lvl27_b1")		until true		dialog.setSkipEnabled(false)    game.success()end